class Poly(dict):
 def __add__(self,other):
  out=Poly(self)
  for key,value in other.items():out[key]=out.get(key,0)+value
  return Poly({k:v for k,v in out.items() if v})
 def __neg__(self):return Poly({k:-v for k,v in self.items()})
 def __sub__(self,other):return self+-other
 def __mul__(self,other):
  out=Poly()
  for k,v in self.items():
   for j,w in other.items():
    key=tuple(sorted(k+j));out[key]=out.get(key,0)+v*w
  return Poly({k:v for k,v in out.items() if v})
